/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_PARTY_HIERARCHY
   anchor      : HUB_PARTY   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 3 emitted of 3 (one per source view AND run)
   runs        : 3 -- opus_health_delta3, opus_health_legacy_v4, opus_health_v2
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_HIERARCHY_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
     SUBORDINATE WRITER on REPORTING_PARENT_REFERENCE: run opus_health_delta3, 1 writer(s), registry/ies HUB_PARTY_BK__PART_ID -- its value is DISCARDED wherever opus_health_v2 also writes the same key
   DECLARED SOURCE PRECEDENCE -- 1 attribute(s) are written by BOTH runs.
   Never a key change and never RECORD_SOURCE in a key: either would
   silently alter grain. Precedence is a VALUE choice, reversible by reload:
     REPORTING_PARENT_REFERENCE                   opus_health_v2 > opus_health_delta3
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUSTOMER_ID))) as HUB_PARTY_HK
        , DEVELOPMENT_CODE as DEVELOPMENT_OFFICER_REFERENCE
        , cast(null as varchar) as REPORTING_PARENT_REFERENCE
        , cast(null as varchar) as TERRITORY_CODE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(CUSTOMER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__INTERMEDIARY_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as DEVELOPMENT_OFFICER_REFERENCE
        , PARTNER_ID as REPORTING_PARENT_REFERENCE
        , REGION_CODE as TERRITORY_CODE
        , 'BJAZ_INTERMEDIARY' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_intermediary') }}
    where (nullif(trim(INTERMEDIARY_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CONTRACT_ID_INSURED_NAME))) as HUB_PARTY_HK
        , cast(null as varchar) as DEVELOPMENT_OFFICER_REFERENCE
        , PARENT_CODE as REPORTING_PARENT_REFERENCE
        , cast(null as varchar) as TERRITORY_CODE
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DEVELOPMENT_OFFICER_REFERENCE end) as DEVELOPMENT_OFFICER_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then REPORTING_PARENT_REFERENCE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then REPORTING_PARENT_REFERENCE end)) as REPORTING_PARENT_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then TERRITORY_CODE end) as TERRITORY_CODE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when DEVELOPMENT_OFFICER_REFERENCE is not null or REPORTING_PARENT_REFERENCE is not null or TERRITORY_CODE is not null
                     then md5(upper(coalesce(cast(DEVELOPMENT_OFFICER_REFERENCE as varchar), '') || '|' || coalesce(cast(REPORTING_PARENT_REFERENCE as varchar), '') || '|' || coalesce(cast(TERRITORY_CODE as varchar), '')))
                end as SAT_PARTY_HIERARCHY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_HIERARCHY_HASHDIFF is not null
